class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:
        sum_digits = sum(int(d) for d in str(x))
        if x % sum_digits == 0:
            return sum_digits
        else:
            return -1

from typing import List

class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        # Collect all indices where the element is x
        indices = []
        for i, num in enumerate(nums):
            if num == x:
                indices.append(i)

        # Process each query
        result = []
        for q in queries:
            if q > len(indices):
                result.append(-1)
            else:
                result.append(indices[q - 1])

        return result

